solution.events.py:
from datetime import datetime

def sort_events(events):
    def instant(event):
        value = datetime.fromisoformat(event['timestamp'])
        if value.tzinfo is None:
            raise ValueError('timezone required')
        return value
    return sorted(events, key=instant)

