solution.settings.py:
import json
from pathlib import Path

def load_settings(path):
    try:
        text = Path(path).read_text(encoding='utf-8')
    except FileNotFoundError:
        return {}
    value = json.loads(text)
    if not isinstance(value, dict):
        raise ValueError('settings must be an object')
    return value

def save_settings(path, values):
    if not isinstance(values, dict):
        raise ValueError('settings must be an object')
    text = json.dumps(values, ensure_ascii=False)
    Path(path).write_text(text, encoding='utf-8')

tasks.verify:
from settings import load_settings,save_settings
from pathlib import Path
import tempfile
with tempfile.TemporaryDirectory() as temp:
    path=Path(temp)/'settings.json'
    assert load_settings(path) == {}
    save_settings(path,{'name':'中文','active':True})
    assert load_settings(path) == {'name':'中文','active':True}
    old=path.read_bytes()
    try: save_settings(path,[])
    except ValueError: pass
    else: raise AssertionError('non-object saved')
    assert path.read_bytes() == old
    for raw in ['{broken','[]','null']:
        path.write_text(raw,encoding='utf-8')
        try: load_settings(path)
        except ValueError: pass
        else: raise AssertionError('invalid config silently accepted')
        assert path.read_text(encoding='utf-8') == raw
